<script setup lang="ts">
import {computed,ref} from 'vue';
import type {Configuration,SnapshotSchedule} from './api';
const props=defineProps<{config:Configuration;admin:boolean;averageAllowed:boolean;licensed:boolean}>(),emit=defineEmits<{dirty:[]}>();
const draft=ref<SnapshotSchedule|null>(null),all=ref(true),agreement=ref(false),error=ref('');
const eligible=computed(()=>draft.value?.kind==='AverageTemperature'?props.config.tanks.filter(t=>t.temperatureMode==='Wireless'&&t.controls.wirelessMeasurementEnabled&&props.config.channels.find(c=>c.id===t.channelId)?.protocol==='DirectRtu'):props.config.tanks);
function add(){draft.value={id:crypto.randomUUID(),name:'',time:'23:55',enabled:true,tankIds:null,kind:'Snapshot',points:5,automaticOperationConfirmed:false,authorizedById:null,authorizedByName:null,authorizedSecurityVersion:0};all.value=true;agreement.value=false;error.value=''}
function edit(s:SnapshotSchedule){draft.value=JSON.parse(JSON.stringify(s));all.value=s.tankIds===null;agreement.value=false;error.value=''}
function kindChanged(){if(!draft.value)return;all.value=draft.value.kind==='Snapshot';draft.value.tankIds=all.value?null:[];agreement.value=false}
function apply(){if(!draft.value)return;if(!draft.value.name.trim()||!all.value&&!draft.value.tankIds?.length){error.value='请填写任务名称并选择储罐';return}if(draft.value.kind==='AverageTemperature'){if(draft.value.enabled&&!agreement.value){error.value='请明确确认定时自动仪表操作授权';return}draft.value.automaticOperationConfirmed=agreement.value;draft.value.authorizedById=null;draft.value.authorizedByName=null;draft.value.authorizedSecurityVersion=0}else if(all.value)draft.value.tankIds=null;draft.value.name=draft.value.name.trim();const i=props.config.schedules.findIndex(s=>s.id===draft.value!.id);if(i<0)props.config.schedules.push(draft.value);else props.config.schedules[i]=draft.value;draft.value=null;emit('dirty')}
function toggle(s:SnapshotSchedule){if(s.kind==='AverageTemperature'&&!s.enabled){edit(s);draft.value!.enabled=true;return}s.enabled=!s.enabled;emit('dirty')}
function remove(s:SnapshotSchedule){if(confirm('删除定时任务 '+s.name+'？已保存记录保留，不取消已受理的测温任务。')){props.config.schedules.splice(props.config.schedules.findIndex(x=>x.id===s.id),1);emit('dirty')}}
</script>
<template><div class="notice">每日按采集主机当地时间申请，同一任务每天最多自动申请一次。错过执行分钟不补跑，服务重启不重发动作。数据快照不操作仪表；测温任务需明确授权，并按协议能力、当前采集状态和账号权限检查。</div><div class="toolbar"><span>新任务保存后生效；已受理测温的取消应在测温任务中处理。</span><button v-if="admin" class="button primary" @click="add">新增定时任务</button></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>任务名称</th><th>类型</th><th>每日时间</th><th>对象</th><th>状态 / 授权</th><th>操作</th></tr></thead><tbody><tr v-for="s in config.schedules" :key="s.id"><td>{{s.name}}</td><td>{{s.kind==='AverageTemperature'?(averageAllowed?'平均温度测量':'未开放的定时任务'):'数据快照'}}</td><td>{{s.time}}</td><td>{{s.tankIds?s.tankIds.map(id=>config.tanks.find(t=>t.id===id)?.code).join('、'):'全部启用储罐（含隐藏罐）'}}</td><td>{{s.enabled?'启用':'停用'}}<small v-if="s.kind==='AverageTemperature'&&averageAllowed">{{s.points}}点 · {{s.authorizedByName||'待保存授权'}}</small></td><td><button v-if="admin" class="text-button" @click="edit(s)">编辑</button><button v-if="admin" class="text-button" @click="toggle(s)">{{s.enabled?'停用':'启用'}}</button><button v-if="admin" class="text-button" @click="remove(s)">删除</button></td></tr><tr v-if="!config.schedules.length"><td colspan="6" class="empty">尚未配置定时任务</td></tr></tbody></table></div></section><div v-if="draft" class="modal-backdrop"><section class="modal" role="dialog" aria-label="定时任务配置"><div class="modal-head"><h2>定时任务配置</h2><button class="button" @click="draft=null">关闭</button></div><div class="modal-body"><p v-if="error" class="error-message">{{error}}</p><form @submit.prevent="apply"><div class="config-fields"><label class="config-field">任务名称<input v-model="draft.name" required maxlength="80"></label><label class="config-field">类型<select v-model="draft.kind" @change="kindChanged"><option value="Snapshot">数据快照</option><option v-if="averageAllowed" value="AverageTemperature" :disabled="!licensed">平均温度测量</option></select></label><label class="config-field">每日时间<input v-model="draft.time" type="time" required></label><label v-if="draft.kind==='AverageTemperature'" class="config-field">选择点数<select v-model.number="draft.points"><option v-for="i in 16" :key="i" :value="i">{{i}}点</option></select></label><label class="checkbox"><input v-model="draft.enabled" type="checkbox">启用任务</label><label v-if="draft.kind==='Snapshot'" class="checkbox"><input v-model="all" type="checkbox" @change="draft.tankIds=all?null:[]">全部启用储罐</label></div><div v-if="!all" class="bulk-tanks"><label v-for="t in eligible" :key="t.id" class="checkbox"><input v-model="draft.tankIds" type="checkbox" :value="t.id">{{t.code}}{{t.enabled?'':' · 已停用'}}</label><span v-if="!eligible.length" class="help">没有符合条件的储罐。</span></div><template v-if="draft.kind==='AverageTemperature'"><p class="notice">定时任务将自动下降浮子、停止并恢复测量Ⅰ。当前仅已开放测温的直连储罐可选择；网关/IFX能力限制继续保留。账号停用、岗位、权限矩阵或密码变化后，原定时授权失效，需重新编辑确认。</p><label class="checkbox"><input v-model="agreement" type="checkbox">已获现场许可，授权每日按此时间、点数和储罐自动执行平均测温</label></template><button class="button primary">应用到待保存配置</button></form></div></section></div></template>
